import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 19 章 自动化工作流的可靠性","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md"}'),l={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md"};function o(i,t,d,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 19 章 自动化工作流的可靠性（易懂版）](../../easy/第19章 自动化工作流的可靠性（易懂版）.md)</p></div><h1 id="第-19-章-自动化工作流的可靠性" tabindex="-1">第 19 章 自动化工作流的可靠性 <a class="header-anchor" href="#第-19-章-自动化工作流的可靠性" aria-label="Permalink to &quot;第 19 章 自动化工作流的可靠性&quot;">​</a></h1><blockquote><p>本章目标：掌握可靠性的三支柱（留痕/验证/人审）、失败处理的正确姿势，以及幂等、可恢复、可回退等进阶能力。<strong>可靠的自动化 = 看得见（留痕）+ 验得出（校验）+ 人把关（人审）。宁可慢一点，不可错得漂亮。</strong></p></blockquote><h2 id="_19-1-自动化最大的敌人-悄悄出错" tabindex="-1">19.1 自动化最大的敌人：悄悄出错 <a class="header-anchor" href="#_19-1-自动化最大的敌人-悄悄出错" aria-label="Permalink to &quot;19.1 自动化最大的敌人：悄悄出错&quot;">​</a></h2><p>自动化最危险的不是&quot;跑不起来&quot;，而是**&quot;看起来在跑，其实错了&quot;**。一份错数据的周报，比没有周报更有害——因为没人会怀疑它。</p><h3 id="_19-1-1-两种失败" tabindex="-1">19.1.1 两种失败 <a class="header-anchor" href="#_19-1-1-两种失败" aria-label="Permalink to &quot;19.1.1 两种失败&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>表现</th><th>危害</th></tr></thead><tbody><tr><td><strong>显性失败</strong></td><td>报错、中断、跑不起来</td><td>低——你能看到</td></tr><tr><td><strong>隐性失败</strong></td><td>跑完了，但结果错</td><td><strong>高——没人会发现</strong></td></tr></tbody></table><p>这一章全部内容，都在对抗&quot;隐性失败&quot;。</p><h2 id="_19-2-可靠性三支柱" tabindex="-1">19.2 可靠性三支柱 <a class="header-anchor" href="#_19-2-可靠性三支柱" aria-label="Permalink to &quot;19.2 可靠性三支柱&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>留痕（Logging）→ 每次运行都有记录</span></span>
<span class="line"><span>验证（Validation）→ 产出自动校验</span></span>
<span class="line"><span>人审（Human-in-the-loop）→ 关键节点人把关</span></span></code></pre></div><p><strong>缺一个，可靠性就塌一角。</strong></p><h3 id="_19-2-1-三支柱的关系" tabindex="-1">19.2.1 三支柱的关系 <a class="header-anchor" href="#_19-2-1-三支柱的关系" aria-label="Permalink to &quot;19.2.1 三支柱的关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>留痕：出了问题能追溯（案发现场）</span></span>
<span class="line"><span>验证：问题在交付前被发现（体检）</span></span>
<span class="line"><span>人审：重要结果有人拍板（最后一公里）</span></span></code></pre></div><p><strong>留痕管过去、验证管现在、人审管未来——三者互补，缺一不可。</strong></p><h2 id="_19-3-支柱一-留痕-logging" tabindex="-1">19.3 支柱一：留痕（Logging） <a class="header-anchor" href="#_19-3-支柱一-留痕-logging" aria-label="Permalink to &quot;19.3 支柱一：留痕（Logging）&quot;">​</a></h2><p>每次运行，自动记录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间、输入（文件/参数）、步骤、关键中间值、输出、耗时</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行日志示例：</span></span>
<span class="line"><span>2026-08-08 18:00:01 开始：合并 3 个 CSV</span></span>
<span class="line"><span>2026-08-08 18:00:03 读取 data/a.csv（1,204 行）</span></span>
<span class="line"><span>2026-08-08 18:00:05 合并完成，共 3,612 行</span></span>
<span class="line"><span>2026-08-08 18:00:06 校验：行数一致 ✓，写入 output/</span></span></code></pre></div><p><strong>出问题时，日志就是案发现场。</strong> 没有日志的自动化 = 没有黑匣子的飞机。</p><h3 id="_19-3-1-日志要记什么" tabindex="-1">19.3.1 日志要记什么 <a class="header-anchor" href="#_19-3-1-日志要记什么" aria-label="Permalink to &quot;19.3.1 日志要记什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>为什么</th></tr></thead><tbody><tr><td>运行时间</td><td>判断是否按时跑</td></tr><tr><td>输入参数</td><td>复现问题必须</td></tr><tr><td>关键中间值</td><td>定位错在哪一步</td></tr><tr><td>输出位置</td><td>找到产物</td></tr><tr><td>耗时</td><td>监控性能退化</td></tr></tbody></table><h2 id="_19-4-支柱二-验证-validation" tabindex="-1">19.4 支柱二：验证（Validation） <a class="header-anchor" href="#_19-4-支柱二-验证-validation" aria-label="Permalink to &quot;19.4 支柱二：验证（Validation）&quot;">​</a></h2><p>自动化内部要自带&quot;体检&quot;，不能交付前才发现：</p><table tabindex="0"><thead><tr><th>检查</th><th>示例</th></tr></thead><tbody><tr><td>数量校验</td><td>输出行数 = 输入行数之和</td></tr><tr><td>格式校验</td><td>日期格式、字段齐全</td></tr><tr><td>内容校验</td><td>关键字段无空值、无重复</td></tr><tr><td>阈值告警</td><td>环比变化 &gt; 50% 时标记异常</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：合并后自动校验&quot;行数 = 1,204 + 1,158 + 1,250 = 3,612&quot;，</span></span>
<span class="line"><span>不通过就报警，不静默通过。</span></span></code></pre></div><h3 id="_19-4-1-校验的设计原则" tabindex="-1">19.4.1 校验的设计原则 <a class="header-anchor" href="#_19-4-1-校验的设计原则" aria-label="Permalink to &quot;19.4.1 校验的设计原则&quot;">​</a></h3><ol><li><strong>可自动化</strong>：用代码检查，不靠人肉抽查；</li><li><strong>足够敏感</strong>：关键错误一定触发告警；</li><li><strong>不误报</strong>：告警阈值别设太低，否则狼来了；</li><li><strong>失败即停</strong>：校验不过，立即停下，不继续往下跑。</li></ol><h2 id="_19-5-支柱三-人审节点-human-in-the-loop" tabindex="-1">19.5 支柱三：人审节点（Human-in-the-loop） <a class="header-anchor" href="#_19-5-支柱三-人审节点-human-in-the-loop" aria-label="Permalink to &quot;19.5 支柱三：人审节点（Human-in-the-loop）&quot;">​</a></h2><p>自动化跑得再稳，<strong>最后一公里永远留给人类</strong>：</p><ul><li>重要输出：生成草稿 → 人确认 → 才发布；</li><li>不可逆操作：先模拟 → 人批准 → 才执行；</li><li>异常处理：自动失败自动暂停，等人决策，不自动重试掩盖问题。</li></ul><h3 id="_19-5-1-人审该放在哪" tabindex="-1">19.5.1 人审该放在哪 <a class="header-anchor" href="#_19-5-1-人审该放在哪" aria-label="Permalink to &quot;19.5.1 人审该放在哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>例子</th><th>原因</th></tr></thead><tbody><tr><td>发布前</td><td>周报发布、对外发送</td><td>对外影响，人把关</td></tr><tr><td>不可逆操作前</td><td>删除、覆盖、推送远程</td><td>出错无法挽回</td></tr><tr><td>高风险决策</td><td>预算调整建议</td><td>判断权在人</td></tr></tbody></table><h2 id="_19-6-处理失败的正确姿势" tabindex="-1">19.6 处理失败的正确姿势 <a class="header-anchor" href="#_19-6-处理失败的正确姿势" aria-label="Permalink to &quot;19.6 处理失败的正确姿势&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>失败 → 停下（不硬跑）→ 记录现场 → 通知人 → 人决策：</span></span>
<span class="line"><span>      修输入重跑 / 修步骤 / 放弃本次</span></span></code></pre></div><p><strong>不要</strong>：失败后自动重试 10 次掩盖问题。</p><h3 id="_19-6-1-失败处理对比" tabindex="-1">19.6.1 失败处理对比 <a class="header-anchor" href="#_19-6-1-失败处理对比" aria-label="Permalink to &quot;19.6.1 失败处理对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>做法</th><th>结果</th></tr></thead><tbody><tr><td>失败即停 + 通知人</td><td>问题暴露，人能干预</td></tr><tr><td>失败自动重试 N 次</td><td>掩盖问题，浪费资源</td></tr><tr><td>失败静默跳过</td><td><strong>最危险</strong>——产物残缺还当成功</td></tr></tbody></table><h2 id="_19-7-可靠性的进阶-幂等与可恢复" tabindex="-1">19.7 可靠性的进阶：幂等与可恢复 <a class="header-anchor" href="#_19-7-可靠性的进阶-幂等与可恢复" aria-label="Permalink to &quot;19.7 可靠性的进阶：幂等与可恢复&quot;">​</a></h2><ul><li><strong>幂等</strong>：同一输入跑两次，结果一样（不会重复发消息、重复扣款）；</li><li><strong>可恢复</strong>：第 3 步失败，修好后从第 3 步继续，而不是从头再来；</li><li><strong>可回退</strong>：本次输出错了，能一键回到上一次正确版本。</li></ul><h3 id="_19-7-1-为什么幂等重要" tabindex="-1">19.7.1 为什么幂等重要 <a class="header-anchor" href="#_19-7-1-为什么幂等重要" aria-label="Permalink to &quot;19.7.1 为什么幂等重要&quot;">​</a></h3><p><strong>自动化经常要重跑</strong>（第一次网络超时、数据源更新）。如果任务不幂等：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>重跑一次 → 重复发了一封邮件 → 重复扣了一次款 → 灾难</span></span></code></pre></div><p><strong>设计原则：任务要能安全地重跑，结果与次数无关。</strong></p><h2 id="_19-8-可靠性检查清单-部署前过一遍" tabindex="-1">19.8 可靠性检查清单（部署前过一遍） <a class="header-anchor" href="#_19-8-可靠性检查清单-部署前过一遍" aria-label="Permalink to &quot;19.8 可靠性检查清单（部署前过一遍）&quot;">​</a></h2><ul><li>[ ] 有运行日志（时间/输入/步骤/输出）？</li><li>[ ] 有自动校验（数量/格式/内容）？</li><li>[ ] 校验失败会停下而不是静默通过？</li><li>[ ] 重要输出前有人审节点？</li><li>[ ] 任务可安全重跑（幂等）？</li><li>[ ] 失败后能恢复/回退？</li></ul><h2 id="_19-9-练习" tabindex="-1">19.9 练习 <a class="header-anchor" href="#_19-9-练习" aria-label="Permalink to &quot;19.9 练习&quot;">​</a></h2><ol><li>找一个你现有的自动化任务，检查它是否三支柱齐全；</li><li>补上日志和校验（至少数量校验）；</li><li>模拟一次失败，确认它会&quot;停下 + 通知人&quot;而不是&quot;静默出错&quot;；</li><li>用 19.8 检查清单给现有自动化打分，补缺口。</li></ol><hr><blockquote><p>小结：可靠的自动化 = <strong>看得见（留痕）+ 验得出（校验）+ 人把关（人审）</strong>。宁可慢一点，不可错得漂亮。下一章：记忆系统进阶。</p></blockquote>`,49)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
